// SPDX-License-Identifier: MIT

//! unitext — Unicode text algorithms on UTF-8 strings: full case mapping (lower, upper,
//! title, capitalize, swapcase, casefold), normalization (NFC, NFD, NFKC, NFKD,
//! quick check, is-normalized), accent folding (`unaccent`), and Python-`str`
//! classification (isAlpha, isDecimal, isDigit, isNumeric, isAlnum, isSpace, isUpper,
//! isLower, isTitle, isPrintable, isAscii) with per-code-point properties.
//!
//! Unicode 17.0.0 (`unicode_version`), generated by `tools/ucd_gen/gen.py` from the
//! Unicode Character Database. Behaviour is CPython's `str` and `unicodedata` (which
//! the tests compare against code point by code point), Rust's `str::to_lowercase`
//! and `unicode-normalization`, and Go's `x/text` normalization; the doc comment of
//! each function says which one it follows and where they differ. Every function takes
//! UTF-8 and returns UTF-8; ill-formed input is an `invalid_utf8` option, `.reject`
//! by default.
//!
//! Not here (SPEC.md says why): collation, grapheme / word / sentence segmentation,
//! bidi, IDNA, East Asian width, language-tailored case rules (Turkish, Lithuanian).

const std = @import("std");
const common = @import("common.zig");
const ucd = @import("ucd.zig");
const t = @import("tables.zig");

pub const meta = .{
    .doc = "Unicode text algorithms on UTF-8: full case mapping (lower/upper/title/capitalize/swapcase/casefold), NFC/NFD/NFKC/NFKD normalization, unaccent, Python-str classification; Unicode 17.0.0",
    .platform_note = "any",
    .targets = .{ .linux64, .linux32, .windows },
    .platform = .any,
    .role = .util,
    .concurrency = .reentrant,
    .model_after = "CPython str + unicodedata, Rust std + unicode-normalization, Go x/text (cases, unicode/norm), ICU",
    .deps = .{},
};

/// The Unicode version of every table in this module.
pub const unicode_version = t.unicode_version;

